 const income=sum(monthEntries.filter(e=>e.kind==='income'&&e.status==='paid'),e=>e.amount),outcome=sum(monthEntries.filter(e=>e.kind==='expense'&&(e.status==='paid'||e.card)),e=>e.amount);
