 async function save(next:Data){validate(next);setBusy(true);try{const r=await fetch('/api/data',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,data:next})});const j:any=await r.json();if(!r.ok)throw Error(j.error);setData(next);setRevision(j.revision);setNotice('Dados salvos com sucesso');return true}finally{setBusy(false)}}
