 async function remove(){try{const n=structuredClone(data);const {type,id}=deleting;if(type==='categories'){n.categories=n.categories.filter(c=>!deleting.names.includes(c));await save(n);setSelectedCategories([]);setSelectingCategories(false);setDeleting(null);return}if(type==='entries'){const target=n.entries.find(e=>e.id===id);if(target?.debtId){const parent=n.entries.find(e=>e.id===target.debtId)!;if(parent.status==='paid')throw Error('Estorne primeiro a quitação final desta dívida.');parent.amount+=target.amount;}else if(target?.originalAmount){if(target.status==='paid'){target.status='pending';delete target.actual;await save(n);setDeleting(null);return}if(n.entries.some(e=>e.debtId===id))throw Error('Exclua os pagamentos parciais vinculados antes de excluir a dívida.');}if(target?.card&&target.kind==='expense'&&n.entries.some(e=>e.kind==='invoice'&&e.card===target.card&&e.invoice===target.invoice))throw Error('Estorne primeiro o pagamento desta fatura para editar suas compras.')}if(type==='accounts'&&(n.entries.some(e=>e.account===id||e.destination===id)||n.reserves.some(r=>r.account===id)||n.cards.some(c=>c.account===id)))throw Error('Esta conta possui vínculos. Remova os vínculos antes de excluí-la.');if(type==='cards'&&n.entries.some(e=>e.card===id))throw Error('Este cartão possui compras vinculadas.');(n as any)[type]=(n as any)[type].filter((x:any)=>x.id!==id);await save(n);setDeleting(null)}catch(e:any){setError(e.message);setDeleting(null)}}
