 {page==='Relatórios'&&<><div className="section-title"><h2>Resultados do mês</h2><input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></div><div className="stats-grid three">{stat('Entradas recebidas',income,<ArrowDownLeft/>,()=>show('Receitas',monthEntries.filter(e=>e.kind==='income'&&e.status==='paid')))}{stat('Despesas do período',outcome,<ArrowUpRight/>,()=>show('Despesas',monthEntries.filter(e=>e.kind==='expense'&&(e.status==='paid'||e.card))))}{stat('Resultado do mês',income-outcome,<TrendingUp/>,()=>show('Lançamentos do mês',monthEntries))}</div><div className="two-col">{['expense','income'].map(kind=>{const list=monthEntries.filter(e=>e.kind===kind&&(e.status==='paid'||e.card)),groups=[...new Set(list.map(e=>kind==='income'?e.origin||'Outras origens':e.category))].map(name=>({name,value:sum(list.filter(e=>(kind==='income'?e.origin||'Outras origens':e.category)===name),e=>e.amount)})).sort((a,b)=>b.value-a.value);return <div className="panel" key={kind}><h2>{kind==='expense'?'Gastos por categoria':'Receitas por origem'}</h2>{groups.map(g=><button className="category-row" key={g.name} onClick={()=>show(g.name,list.filter(e=>(kind==='income'?e.origin||'Outras origens':e.category)===g.name))}><div><span>{g.name}</span><strong>{money(g.value)}</strong></div><div className="progress"><i style={{width:g.value/Math.max(1,sum(groups,g=>g.value))*100+'%'}}/></div></button>)}{!groups.length&&emptyState('Ainda sem dados neste mês.')}</div>})}</div><div className="panel"><h2>Pessoal × Empresa</h2>{['PF','PJ'].map(s=><button className="health-line full" key={s} onClick={()=>show('Despesas '+s,monthEntries.filter(e=>e.scope===s&&e.kind==='expense'&&(e.status==='paid'||e.card)))}><span>{s==='PF'?'Despesas pessoais':'Despesas empresariais'}</span><strong>{money(sum(monthEntries.filter(e=>e.scope===s&&e.kind==='expense'&&(e.status==='paid'||e.card)),e=>e.amount))}</strong></button>)}</div></>}
